        normFld_n[2] = dualFld_n[2] / norm1;

        normFld_n[3] = dualFld_n[3] / norm2;
        normFld_n[4] = dualFld_n[4] / norm2;
        normFld_n[5] = dualFld_n[5] / norm2;

        normFld_n[6] = dualFld_n[6] / norm3;
        normFld_n[7] = dualFld_n[7] / norm3;
        normFld_n[8] = dualFld_n[8] / norm3;

        // Set e^m \dot curl(bhat)
        dualcurlbhat_n[0] = dualFld_n[0] * curlbhat_n[0] + dualFld_n[1] * curlbhat_n[1] +
                            dualFld_n[2] * curlbhat_n[2];
        dualcurlbhat_n[1] = dualFld_n[3] * curlbhat_n[0] + dualFld_n[4] * curlbhat_n[1] +
                            dualFld_n[5] * curlbhat_n[2];
        dualcurlbhat_n[2] = dualFld_n[6] * curlbhat_n[0] + dualFld_n[7] * curlbhat_n[1] +
                            dualFld_n[8] * curlbhat_n[2];

        // Set e^3 \dot B
        B3_n[0] =
          dualFld_n[6] * B_cart.x[0] + dualFld_n[7] * B_cart.x[1] + dualFld_n[8] * B_cart.x[2];

        // Set e^m \dot curl(bhat)/|B|.
        dualcurlbhatoverB_n[0] = dualcurlbhat_n[0] / bmag_n[0];
        dualcurlbhatoverB_n[1] = dualcurlbhat_n[1] / bmag_n[0];
        dualcurlbhatoverB_n[2] = dualcurlbhat_n[2] / bmag_n[0];

        // Signed B^3/|B| controls streaming along the third coordinate.
        rtg33inv_n[0] = B3_n[0] / bmag_n[0];

        // set b_i/JB
        for (int i = 0; i < 3; ++i) {
          bioverJB_n[i] = biFld_n[i] / (J * bmag_n[0]);
        }
      }
    }
  }

  gkyl_nodal_ops_n2m(
    up->n2m, up->cbasis, up->grid, &gk_geom->nrange_int, &gk_geom->local, 3,
    gk_geom->geo_int.mc2p_nodal, gk_geom->geo_int.mc2p, true
  );
  gkyl_nodal_ops_n2m(
    up->n2m, up->cbasis, up->grid, &gk_geom->nrange_int, &gk_geom->local, 1,
        double *normcurlbhat_n = gkyl_array_fetch(
          gk_geom->geo_surf[dir].normcurlbhat_nodal,
          gkyl_range_idx(&gk_geom->nrange_surf[dir], cidx)
        );

        // Set mapc2p
        mc2p_n[0] = mirror_rza_n[0]; // R
        mc2p_n[1] = mirror_rza_n[1]; // Z
        mc2p_n[2] = mirror_rza_n[2]; // PHI
        // Set bmag
        struct gkyl_vec3 B_cart =
          gkyl_vec3_polar_con_to_cart(mirror_rza_n[0], mirror_rza_n[2], mirror_geo_n->B);
        bmag_n[0] = gkyl_vec3_len(B_cart);
        // Set Jacobian
        jFld_n[0] = mirror_geo_n->Jc;
        // Set curl(bhat)
        struct gkyl_vec3 curlbhat_cart =
          gkyl_vec3_polar_con_to_cart(mirror_rza_n[0], mirror_rza_n[2], mirror_geo_n->curlbhat);
        curlbhat_n[0] = curlbhat_cart.x[0];
        curlbhat_n[1] = curlbhat_cart.x[1];
        curlbhat_n[2] = curlbhat_cart.x[2];
        // Set tangents and duals
        for (int ivec = 0; ivec < 3; ivec++) {
          struct gkyl_vec3 tan =
            gkyl_vec3_polar_con_to_cart(mirror_rza_n[0], mirror_rza_n[2], mirror_geo_n->tang[ivec]);
          struct gkyl_vec3 dual =
            gkyl_vec3_polar_con_to_cart(mirror_rza_n[0], mirror_rza_n[2], mirror_geo_n->dual[ivec]);
          tanvecFld_n[ivec * 3 + 0] = tan.x[0];
          tanvecFld_n[ivec * 3 + 1] = tan.x[1];
          tanvecFld_n[ivec * 3 + 2] = tan.x[2];
          dualFld_n[ivec * 3 + 0] = dual.x[0];
          dualFld_n[ivec * 3 + 1] = dual.x[1];
          dualFld_n[ivec * 3 + 2] = dual.x[2];
        }
        // Set metric tensor
        int count = 0;
        for (int i = 0; i < 3; ++i) {
          for (int j = 0; j < 3; ++j) {
            if (i > j) {
              continue;
            }
            gFld_n[count] = tanvecFld_n[3 * i + 0] * tanvecFld_n[3 * j + 0] +
                            tanvecFld_n[3 * i + 1] * tanvecFld_n[3 * j + 1] +
                            tanvecFld_n[3 * i + 2] * tanvecFld_n[3 * j + 2];
            count++;
          }
        }

        // Set derived quantities
        double R = mc2p_n[R_IDX];
        double Z = mc2p_n[Z_IDX];
        double J = jFld_n[0];
        double phi = mc2p_n[PHI_IDX];

        // Calculate bhat and its covariant components from the magnetic vector.
        for (int i = 0; i < 3; ++i) {
          bcartFld_n[i] = B_cart.x[i] / bmag_n[0];
        }
        for (int i = 0; i < 3; ++i) {
          biFld_n[i] = tanvecFld_n[3 * i] * bcartFld_n[0] + tanvecFld_n[3 * i + 1] * bcartFld_n[1] +
                       tanvecFld_n[3 * i + 2] * bcartFld_n[2];
        }

        // cmag is a magnitude; reversing B leaves it and J|B| unchanged.
        cmagFld_n[0] = jFld_n[0] * bmag_n[0] / sqrt(gFld_n[5]);
        double *jtotinvFld_n = gkyl_array_fetch(
          gk_geom->geo_surf[dir].jacobtot_inv_nodal,
          gkyl_range_idx(&gk_geom->nrange_surf[dir], cidx)
        );
        jtotinvFld_n[0] = 1.0 / (jFld_n[0] * bmag_n[0]);

        double norm1 = sqrt(
          dualFld_n[0] * dualFld_n[0] + dualFld_n[1] * dualFld_n[1] + dualFld_n[2] * dualFld_n[2]
        );
        double norm2 = sqrt(
          dualFld_n[3] * dualFld_n[3] + dualFld_n[4] * dualFld_n[4] + dualFld_n[5] * dualFld_n[5]
        );
        double norm3 = sqrt(
          dualFld_n[6] * dualFld_n[6] + dualFld_n[7] * dualFld_n[7] + dualFld_n[8] * dualFld_n[8]
        );

        dualmagFld_n[0] = norm1;
        dualmagFld_n[1] = norm2;
        dualmagFld_n[2] = norm3;

        // Set normal vectors
        normFld_n[0] = dualFld_n[0] / norm1;
        normFld_n[1] = dualFld_n[1] / norm1;
        normFld_n[2] = dualFld_n[2] / norm1;

        normFld_n[3] = dualFld_n[3] / norm2;
        normFld_n[4] = dualFld_n[4] / norm2;
        normFld_n[5] = dualFld_n[5] / norm2;

        normFld_n[6] = dualFld_n[6] / norm3;
        normFld_n[7] = dualFld_n[7] / norm3;
        normFld_n[8] = dualFld_n[8] / norm3;

        // Set lenr
        lenr_n[0] = J * dualmagFld_n[dir];

        // Set n^3 \dot B
        B3_n[0] =
          normFld_n[6] * B_cart.x[0] + normFld_n[7] * B_cart.x[1] + normFld_n[8] * B_cart.x[2];

        // Set n^m \dot curl(bhat)
        normcurlbhat_n[0] = normFld_n[3 * dir + 0] * curlbhat_n[0] +
                            normFld_n[3 * dir + 1] * curlbhat_n[1] +
                            normFld_n[3 * dir + 2] * curlbhat_n[2];
      }
    }
  }
